p='/tmp/gbrain-install-docs/mcp-check.ts'
s=open(p).read();s=s[:s.index('try {')]+'''const mode=process.argv[2];
const file='/tmp/gbrain-install-docs/mcp-roundtrip.json';
async function call(name:string,args:any){const r=await client.callTool({name,arguments:args,_meta:{hot_memory:'off'}});console.log(JSON.stringify({tool:name,result:r},null,2));if(r.isError)throw new Error(name+' returned isError');const d=r.structuredContent ?? JSON.parse((r.content as any[]).find(c=>c.type==='text').text);return d;}
try {
 await client.connect(transport);
 if(mode==='remember'){
  const marker='mcp-install-check-'+crypto.randomUUID();
  const d=await call('remember',{fact:'Generic GBrain MCP installation test: '+marker,entity:'gbrain-mcp-install-check',provenance:'install-check',request_id:crypto.randomUUID()});
  if(!d.id)throw new Error('No fact id returned');
  await Bun.write(file,JSON.stringify({id:String(d.id),marker}));
 } else {
  const state=await Bun.file(file).json();
  const d=await call('recall',{entity:'gbrain-mcp-install-check'});
  if(!JSON.stringify(d).includes(state.marker))throw new Error('Saved marker not recalled');
  if(mode==='cleanup'){
   await call('forget',{id:state.id,reason:'install-check cleanup',request_id:crypto.randomUUID()});
   const after=await call('recall',{entity:'gbrain-mcp-install-check'});
   if(JSON.stringify(after).includes(state.marker))throw new Error('Marker still active');
  }
 }
} finally { await client.close(); }
'''
open(p,'w').write(s)
